reference_solution:
def count_without_consecutive_ones(n):
    counts = [1, 2]
    for _ in range(2, 32):
        counts.append(counts[-1] + counts[-2])
    answer = 0
    previous = 0
    for bit in range(30, -1, -1):
        if n & (1 << bit):
            answer += counts[bit]
            if previous:
                return answer
            previous = 1
        else:
            previous = 0
    return answer + 1

